foreach (var msg in batch)
{
    if (string.IsNullOrWhiteSpace(msg.Body))
    {
        continue; // skip this message, process the rest
    }
    Process(msg);
}

return 0; // process exit code: success

switch (kind)
{
    case 1:
    case 2:
        HandleSmall(); // stacked labels share one body
        break;
    case 3:
        LogWarning();
        goto case 1;    // explicit fall-through to case 1 logic
    default:
        HandleOther();
        break;
}

int ProcessOrder(Order? order)
{
    if (order is null)
        return -1; // early exit: invalid input

    if (order.Items.Count == 0)
        return -2; // early exit: empty order

    // main logic — no else nesting needed
    Submit(order);
    return 0;
}
